ruleSearch.coverUrl:
tag.a.1@href
<js>
var id = result.match(/\/(\d+).*/)[1];
var iid = parseInt(id/1000);
'/files/article/image/'+iid+'/'+id+'/'+id+'s.jpg';
</js>

header:
{
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/112.0.0.0 Safari/537.36"
}

